// Bird song journal: BirdWeather detections -> OpenAI field-journal plates -> a
// cycling collection on the frame.
//
// BirdWeather is a network of listening stations that run BirdNET on live audio,
// so this journal fills up with birds that were actually *heard* near you rather
// than ones somebody photographed.
//
// Each render:
//  1. Poll the BirdWeather GraphQL API (rate-limited by pollMinutes) for the
//     species heard in the last daysWindow days, either inside a box around the
//     configured spot or at specific stations, and log every species along with
//     BirdWeather's licensed reference photo.
//  2. If a logged species has no plate yet, draw one: the reference photo and
//     the configured style go to the OpenAI Responses API image_generation tool,
//     and the model then double-checks the plate against the reference.
//     Verified plates are saved as PNG assets. One attempt per render.
//  3. Show the next plate in the collection (first heard first) and write a
//     caption line to scene state for a text overlay.
//
// The species log lives in scene state under journalStateKey; declare that key
// as a disk-persisted scene field so the collection survives restarts.

const PAPER_COLOR = "#f5f1e6"
const REFERENCE_PHOTOS_PER_PLATE = 2
// Recent detections are only read to learn when and where each species was last
// heard nearby; the roster itself comes from topSpecies.
const RECENT_DETECTIONS = 50

// One round trip: the species roster with window counts, plus the newest local
// detections. Species.latestDetections is deliberately not used — it is global,
// so it happily reports a station on another continent.
const JOURNAL_QUERY = `query FrameOSBirdSongJournal(
  $period: InputDuration, $ne: InputLocation, $sw: InputLocation,
  $stationIds: [ID!], $classifications: [String!], $limit: Int, $recent: Int
) {
  topSpecies(
    period: $period, ne: $ne, sw: $sw, stationIds: $stationIds,
    classifications: $classifications, limit: $limit
  ) {
    count
    species { id commonName scientificName imageUrl imageCredit imageLicense }
  }
  detections(
    period: $period, ne: $ne, sw: $sw, stationIds: $stationIds,
    classifications: $classifications, first: $recent
  ) {
    speciesCount
    totalCount
    nodes { speciesId timestamp station { name } }
  }
}`

function readJournal(app, key) {
  const stored = app.state[key]
  if (stored && typeof stored === "object" && stored.species) {
    return stored
  }
  return { species: {}, cursor: 0, lastPollAt: 0 }
}

function slugify(name) {
  return String(name).toLowerCase().replace(/[^a-z0-9]+/g, "-").replace(/^-+|-+$/g, "")
}

function isoDate(millis) {
  return new Date(millis).toISOString().slice(0, 10)
}

function formatCount(value) {
  return String(Number(value) || 0).replace(/\B(?=(\d{3})+(?!\d))/g, ",")
}

function commaList(value) {
  return String(value || "").split(",").map((part) => part.trim()).filter((part) => part.length > 0)
}

// Degrees per km, with the longitude span widened by latitude. The poles would
// divide by ~0, so the cosine is clamped well before it gets there.
function boundingBox(lat, lng, radiusKm) {
  const latSpan = radiusKm / 111.32
  const lngSpan = radiusKm / (111.32 * Math.max(0.01, Math.cos(lat * Math.PI / 180)))
  return {
    ne: { lat: Math.min(90, lat + latSpan), lon: Math.min(180, lng + lngSpan) },
    sw: { lat: Math.max(-90, lat - latSpan), lon: Math.max(-180, lng - lngSpan) },
  }
}

function plateSize(app, context) {
  let width = context.imageWidth || 0
  let height = context.imageHeight || 0
  if (!width || !height) {
    width = app.frame.width
    height = app.frame.height
    if (app.frame.rotate === 90 || app.frame.rotate === 270) {
      const swap = width
      width = height
      height = swap
    }
  }
  return height >= width ? "1024x1536" : "1536x1024"
}

// BirdWeather credits are HTML fragments linking the photographer.
function creditLine(species) {
  const credit = String(species.imageCredit || "")
    .replace(/<[^>]*>/g, "")
    .replace(/\s+/g, " ")
    .trim()
  const license = String(species.imageLicense || "").trim()
  if (credit && license) {
    return `${credit} (${license})`
  }
  return credit || license
}

function birdweatherQuery(app, variables) {
  const res = frameos.httpRequest(`${app.config.birdweatherHost}/graphql`, {
    method: "POST",
    headers: {
      "Content-Type": "application/json",
      "Accept": "application/json",
    },
    body: JSON.stringify({ query: JOURNAL_QUERY, variables }),
    timeoutMs: 30000,
  })
  if (res.status !== 200) {
    return { error: res.error || `HTTP ${res.status}` }
  }
  let parsed = null
  try {
    parsed = JSON.parse(res.body)
  } catch (err) {
    return { error: "unparseable response" }
  }
  // GraphQL reports query errors with HTTP 200, so the envelope needs checking.
  const errors = (parsed && parsed.errors) || []
  if (errors.length) {
    return { error: errors[0].message || "GraphQL error" }
  }
  if (!parsed || !parsed.data) {
    return { error: "empty response" }
  }
  return { data: parsed.data }
}

function pollDetections(app, journal, lat, lng, stationIds, now) {
  const cfg = app.config
  const days = Math.max(1, Number(cfg.daysWindow) || 7)
  const variables = {
    period: { count: days, unit: "day" },
    limit: Math.max(1, Number(cfg.speciesLimit) || 40),
    recent: RECENT_DETECTIONS,
    stationIds: stationIds.length ? stationIds : null,
    classifications: commaList(cfg.classifications),
    ne: null,
    sw: null,
  }
  if (!variables.classifications.length) {
    variables.classifications = null
  }
  // Stations and a location box would intersect, so following stations wins.
  if (!stationIds.length) {
    const box = boundingBox(lat, lng, Math.max(1, Number(cfg.radiusKm) || 25))
    variables.ne = box.ne
    variables.sw = box.sw
  }

  const result = birdweatherQuery(app, variables)
  if (result.error) {
    return { error: result.error }
  }
  const top = result.data.topSpecies || []
  const recentDetections = result.data.detections || {}

  // The newest detection per species. BirdWeather sorts these newest first, but
  // a box can span time zones, so compare the parsed instants rather than trust
  // the order or the offset-bearing strings.
  const latest = {}
  for (const detection of recentDetections.nodes || []) {
    const key = String(detection.speciesId)
    const heardAt = detection.timestamp || ""
    const at = Date.parse(heardAt)
    if (!isFinite(at)) {
      continue
    }
    if (!latest[key] || at > latest[key].at) {
      latest[key] = {
        at,
        heardAt,
        station: (detection.station && detection.station.name) || "",
      }
    }
  }

  const minDetections = Math.max(1, Number(cfg.minDetections) || 1)
  const heard = {}
  let newSpecies = 0
  for (const row of top) {
    const species = row.species
    // No reference photo means no plate can be drawn from it.
    if (!species || !species.id || !species.imageUrl) {
      continue
    }
    const count = Number(row.count) || 0
    // BirdNET guesses at the edge of its confidence produce one-off species.
    if (count < minDetections) {
      continue
    }
    const key = String(species.id)
    heard[key] = true
    let entry = journal.species[key]
    if (!entry) {
      entry = {
        speciesId: species.id,
        name: species.scientificName || species.commonName,
        commonName: species.commonName || species.scientificName,
        firstHeard: isoDate(now),
        detections: 0,
        attempts: 0,
        photos: [],
      }
      journal.species[key] = entry
      newSpecies += 1
    }
    entry.detections = count
    entry.photos = [{ url: species.imageUrl, attribution: creditLine(species) }]
    entry.lastHeard = isoDate(now)
    const recent = latest[key]
    if (recent) {
      entry.heardAt = recent.heardAt
      entry.station = recent.station
    }
  }
  // Counts reflect the current window, so species that dropped out of it fall
  // back to zero and become the first candidates for pruning.
  for (const key of Object.keys(journal.species)) {
    if (!heard[key]) {
      journal.species[key].detections = 0
    }
  }

  return {
    newSpecies,
    speciesHeard: Number(recentDetections.speciesCount) || top.length,
    totalDetections: Number(recentDetections.totalCount) || 0,
  }
}

function openaiResponses(app, body) {
  const apiKey = frameos.getSetting("openAI", "apiKey") || ""
  const res = frameos.httpRequest(`${app.config.openaiHost}/v1/responses`, {
    method: "POST",
    headers: {
      "Authorization": `Bearer ${apiKey}`,
      "Content-Type": "application/json",
    },
    body: JSON.stringify(body),
    timeoutMs: 300000,
  })
  const ok = res.status === 200
  if (!ok) {
    let message = res.error || `HTTP ${res.status}`
    try {
      message = JSON.parse(res.body).error.message || message
    } catch (err) {}
    return { error: message }
  }
  try {
    return { json: JSON.parse(res.body) }
  } catch (err) {
    return { error: "unparseable response" }
  }
}

function extractGeneratedImage(json) {
  for (const item of (json && json.output) || []) {
    if (item.type === "image_generation_call" && item.result) {
      return item.result
    }
  }
  return null
}

function extractOutputText(json) {
  let text = ""
  for (const item of (json && json.output) || []) {
    if (item.type === "message") {
      for (const part of item.content || []) {
        if (part.text) {
          text += part.text
        }
      }
    }
  }
  return text
}

function fetchReferenceDataUrls(app, entry) {
  const refs = []
  for (const photo of entry.photos || []) {
    if (refs.length >= REFERENCE_PHOTOS_PER_PLATE) {
      break
    }
    const res = frameos.httpRequest(photo.url, { base64: true, timeoutMs: 30000 })
    if (res.status === 200 && res.bodyBase64) {
      refs.push(`data:image/jpeg;base64,${res.bodyBase64}`)
    }
  }
  return refs
}

function generatePlate(app, entry, size, refs) {
  const cfg = app.config
  const prompt = `${cfg.style}\n\n` +
    `Species: ${entry.commonName} (${entry.name}).\n` +
    `Use the attached reference photo(s) only to get the plumage colours, bill shape, ` +
    `eye colour and proportions right; compose an original plate, do not copy a photo.\n` +
    `Letter the labels exactly as "${entry.commonName}" and "${entry.name}".`
  const content = [{ type: "input_text", text: prompt }]
  for (const ref of refs) {
    content.push({ type: "input_image", image_url: ref })
  }
  const result = openaiResponses(app, {
    model: cfg.model,
    input: [{ role: "user", content }],
    tools: [{
      type: "image_generation",
      size,
      quality: cfg.imageQuality || "medium",
      output_format: "png",
    }],
    tool_choice: { type: "image_generation" },
  })
  if (result.error) {
    return { error: result.error }
  }
  const image = extractGeneratedImage(result.json)
  if (!image) {
    return { error: "no image in response" }
  }
  return { image }
}

function verifyPlate(app, entry, plateBase64, refs) {
  const prompt = `You are checking a generated field-journal illustration before it joins a birding collection.\n` +
    `Species: ${entry.commonName} (${entry.name}).\n` +
    `The first image is the generated plate; any further images are reference photos of the species.\n` +
    `Reply with strict JSON only: {"ok": true, "reason": "..."} or {"ok": false, "reason": "..."}.\n` +
    `Say ok=true only if the illustrated bird could reasonably be identified as this species ` +
    `(plumage colours, bill shape, overall proportions match the references) and all lettering ` +
    `on the plate is legible and spells the names correctly.`
  const content = [
    { type: "input_text", text: prompt },
    { type: "input_image", image_url: `data:image/png;base64,${plateBase64}` },
  ]
  for (const ref of refs) {
    content.push({ type: "input_image", image_url: ref })
  }
  const result = openaiResponses(app, {
    model: app.config.model,
    input: [{ role: "user", content }],
  })
  if (result.error) {
    return { ok: false, reason: result.error }
  }
  const text = extractOutputText(result.json)
  const match = text.match(/\{[\s\S]*\}/)
  if (!match) {
    return { ok: false, reason: "unparseable verdict" }
  }
  try {
    const verdict = JSON.parse(match[0])
    return { ok: verdict.ok === true, reason: verdict.reason || "" }
  } catch (err) {
    return { ok: false, reason: "unparseable verdict" }
  }
}

function drawPendingPlate(app, context, journal, entry, now) {
  const cfg = app.config
  const refs = fetchReferenceDataUrls(app, entry)
  if (!refs.length) {
    entry.attempts += 1
    entry.lastError = "no reference photo downloadable"
    return { error: `${entry.commonName}: ${entry.lastError}` }
  }

  frameos.log(`Drawing plate for ${entry.commonName} (${entry.name}), attempt ${entry.attempts + 1}`)
  const generated = generatePlate(app, entry, plateSize(app, context), refs)
  if (generated.error) {
    entry.attempts += 1
    entry.lastError = generated.error
    return { error: `${entry.commonName}: ${generated.error}` }
  }

  if (cfg.verifyPlates) {
    const verdict = verifyPlate(app, entry, generated.image, refs.slice(0, 1))
    if (!verdict.ok) {
      entry.attempts += 1
      entry.lastError = `verification failed: ${verdict.reason}`
      frameos.log(`Plate for ${entry.commonName} rejected: ${verdict.reason}`)
      return { error: `${entry.commonName}: ${entry.lastError}` }
    }
  }

  const folder = cfg.assetFolder || "birdSongJournal"
  const path = `${folder}/${entry.speciesId}-${slugify(entry.name)}.png`
  if (!frameos.writeAsset(path, generated.image)) {
    entry.attempts += 1
    entry.lastError = "could not save plate asset"
    return { error: `${entry.commonName}: ${entry.lastError}` }
  }
  entry.plate = path
  entry.lastError = ""
  entry.plateDrawnOn = isoDate(now)
  frameos.log(`Added ${entry.commonName} to the journal: ${path}`)
  return {}
}

function pruneCollection(app, journal) {
  const maxSpecies = Math.max(1, Number(app.config.maxSpecies) || 24)
  const entries = Object.values(journal.species)
  if (entries.length <= maxSpecies) {
    return false
  }
  entries.sort((a, b) => String(a.lastHeard || a.firstHeard || "").localeCompare(String(b.lastHeard || b.firstHeard || "")))
  let toRemove = entries.length - maxSpecies
  for (const entry of entries) {
    if (toRemove <= 0) {
      break
    }
    if (entry.plate) {
      frameos.deleteAsset(entry.plate)
    }
    delete journal.species[String(entry.speciesId)]
    toRemove -= 1
  }
  return true
}

export function get(app, context) {
  const cfg = app.config
  const now = Date.now()
  const journalKey = cfg.journalStateKey || "birdSongJournal"
  const captionKey = cfg.captionStateKey || "birdCaption"
  const journal = readJournal(app, journalKey)
  const notes = []

  const lat = parseFloat(cfg.latitude)
  const lng = parseFloat(cfg.longitude)
  const hasCoords = isFinite(lat) && isFinite(lng)
  const stationIds = commaList(cfg.stationIds)
  const canListen = stationIds.length > 0 || hasCoords

  if (canListen) {
    const pollMillis = Math.max(1, Number(cfg.pollMinutes) || 60) * 60000
    if (now - (journal.lastPollAt || 0) >= pollMillis) {
      const poll = pollDetections(app, journal, lat, lng, stationIds, now)
      if (poll.error) {
        notes.push(`BirdWeather: ${poll.error}`)
        frameos.error(`BirdWeather poll failed: ${poll.error}`)
      } else {
        journal.lastPollAt = now
        journal.lastPoll = {
          speciesHeard: poll.speciesHeard,
          totalDetections: poll.totalDetections,
        }
        if (poll.newSpecies) {
          frameos.log(`Heard ${poll.newSpecies} new species`)
        }
      }
      frameos.setState(journalKey, journal)
    }
  } else {
    notes.push("set latitude and longitude, or a station ID, to begin")
  }

  const maxAttempts = Math.max(1, Number(cfg.maxAttempts) || 3)
  // Oldest discovery first, then the birds heard most — so the ones you are
  // most likely to hear out of the window get drawn while the key is warm.
  const pending = Object.values(journal.species)
    .filter((e) => !e.plate && e.attempts < maxAttempts)
    .sort((a, b) =>
      String(a.firstHeard || "").localeCompare(String(b.firstHeard || "")) ||
      (Number(b.detections) || 0) - (Number(a.detections) || 0))
  const hasApiKey = (frameos.getSetting("openAI", "apiKey") || "").length > 0

  if (pending.length && hasApiKey) {
    const outcome = drawPendingPlate(app, context, journal, pending[0], now)
    if (outcome.error) {
      notes.push(outcome.error)
    }
    frameos.setState(journalKey, journal)
    if (pending.length > 1) {
      frameos.setNextSleep(20)
    }
  } else if (pending.length) {
    notes.push(`${pending.length} plate${pending.length === 1 ? "" : "s"} waiting for an OpenAI API key`)
  }

  if (pruneCollection(app, journal)) {
    frameos.setState(journalKey, journal)
  }

  // Detection counts move with every poll, so the collection is ordered by
  // discovery and then by name — a plate must not jump around as birds sing.
  const plates = Object.values(journal.species)
    .filter((e) => e.plate)
    .sort((a, b) =>
      String(a.firstHeard || "").localeCompare(String(b.firstHeard || "")) ||
      String(a.commonName || "").localeCompare(String(b.commonName || "")))

  if (plates.length) {
    const index = (journal.cursor || 0) % plates.length
    journal.cursor = index + 1
    frameos.setState(journalKey, journal)
    const entry = plates[index]
    const image = frameos.loadAssetImage(entry.plate)
    if (image) {
      const days = Math.max(1, Number(cfg.daysWindow) || 7)
      let caption = entry.commonName
      if (entry.name && entry.name !== entry.commonName) {
        caption += ` — ${entry.name}`
      }
      const detections = Number(entry.detections) || 0
      if (detections) {
        caption += ` · heard ${formatCount(detections)}× in ${days} day${days === 1 ? "" : "s"}`
      } else {
        caption += ` · not heard in the last ${days} day${days === 1 ? "" : "s"}`
      }
      if (entry.station) {
        // "2026-08-10T18:56:33+02:00" -> "18:56", in the station's own timezone.
        const clock = String(entry.heardAt || "").slice(11, 16)
        caption += clock ? ` · last ${clock} at ${entry.station}` : ` · last at ${entry.station}`
      }
      caption += ` · ${index + 1}/${plates.length}`
      if (notes.length) {
        caption += `\n${notes.join(" · ")}`
      }
      frameos.setState(captionKey, caption)
      return image
    }
    notes.push(`missing plate file for ${entry.commonName}`)
  }

  const speciesCount = Object.keys(journal.species).length
  const lastPoll = journal.lastPoll || {}
  let status = "Bird song journal"
  if (speciesCount) {
    status += ` · ${speciesCount} species heard, drawing plates`
  } else if (journal.lastPollAt && !lastPoll.totalDetections) {
    status += stationIds.length
      ? ` · station ${stationIds.join(", ")} has not heard anything yet`
      : ` · no BirdWeather station is listening within ${Math.max(1, Number(cfg.radiusKm) || 25)} km — try a wider radius`
  } else if (stationIds.length) {
    status += ` · listening in on station ${stationIds.join(", ")}`
  } else if (hasCoords) {
    status += ` · listening near ${lat.toFixed(2)}, ${lng.toFixed(2)}`
  }
  if (lastPoll.totalDetections) {
    status += `\n${formatCount(lastPoll.totalDetections)} songs from ${formatCount(lastPoll.speciesHeard)} species nearby`
  }
  if (notes.length) {
    status += `\n${notes.join(" · ")}`
  }
  frameos.setState(captionKey, status)
  return frameos.image({ color: PAPER_COLOR })
}

sources.config.json:
{
  "name": "Bird song journal (JS)",
  "category": "data",
  "description": "Asks BirdWeather which birds its listening stations actually heard near you. Every new species gets a field-journal plate drawn by OpenAI from BirdWeather's licensed reference photo, verified for accuracy, and saved to the asset collection. Cycles through the collection on each render.",
  "version": "1.0.0",
  "settings": ["openAI"],
  "fields": [
    {
      "name": "latitude",
      "label": "Latitude",
      "type": "string",
      "value": "",
      "placeholder": "50.85",
      "hint": "Centre of the listening area. Leave this and the station IDs empty to pause the journal."
    },
    {
      "name": "longitude",
      "label": "Longitude",
      "type": "string",
      "value": "",
      "placeholder": "4.35"
    },
    {
      "name": "radiusKm",
      "label": "Radius (km)",
      "type": "float",
      "value": "25",
      "hint": "BirdWeather stations are sparse outside cities — widen this if nothing turns up."
    },
    {
      "name": "stationIds",
      "label": "BirdWeather station IDs",
      "type": "string",
      "value": "",
      "placeholder": "6767",
      "hint": "Comma-separated. Set this to follow specific stations (your own PUC, say) and the area above is ignored."
    },
    {
      "name": "daysWindow",
      "label": "Time window (days)",
      "type": "integer",
      "value": "7",
      "hint": "Only birds heard within this many days count."
    },
    {
      "name": "pollMinutes",
      "label": "Poll every (minutes)",
      "type": "integer",
      "value": "60",
      "hint": "How often to ask BirdWeather what it has been hearing."
    },
    {
      "name": "speciesLimit",
      "label": "Species per poll",
      "type": "integer",
      "value": "40",
      "hint": "How many of the most-heard species to take from each poll"
    },
    {
      "name": "minDetections",
      "label": "Minimum detections",
      "type": "integer",
      "value": "3",
      "hint": "Ignore species heard fewer times than this in the window — BirdNET's one-off guesses"
    },
    {
      "name": "classifications",
      "label": "Classifications",
      "type": "string",
      "value": "avian",
      "hint": "Comma-separated BirdWeather classifications. Leave empty for everything the stations identify."
    },
    {
      "name": "style",
      "label": "Plate style",
      "type": "text",
      "value": "A 19th-century naturalist's field-journal plate on lightly aged cream paper: fine ink linework with soft watercolor washes. The bird perches on a small branch or stands in typical habitat, anatomically accurate, with its bill open mid-song. Around it, small pencil detail studies (head, wing or feather), a small hand-drawn sonogram or sound-wave sketch in one margin as if the bird had been logged by ear, and short handwritten-style margin notes. Neatly hand-lettered at the bottom: the common name in larger letters and the scientific name in italics beneath it."
    },
    {
      "name": "model",
      "label": "OpenAI model",
      "type": "string",
      "value": "gpt-5.1",
      "hint": "Responses API model that drives image generation and the accuracy check"
    },
    {
      "name": "imageQuality",
      "label": "Plate quality",
      "type": "select",
      "options": ["low", "medium", "high"],
      "value": "medium"
    },
    {
      "name": "verifyPlates",
      "label": "Verify plates",
      "type": "boolean",
      "value": "true",
      "hint": "Have the model double-check each plate against the reference photo before adding it"
    },
    {
      "name": "maxSpecies",
      "label": "Max species kept",
      "type": "integer",
      "value": "24",
      "hint": "Least recently heard species (and their plates) are pruned beyond this"
    },
    {
      "name": "maxAttempts",
      "label": "Max attempts per species",
      "type": "integer",
      "value": "3"
    },
    {
      "name": "assetFolder",
      "label": "Asset folder",
      "type": "string",
      "value": "birdSongJournal",
      "hint": "Plates are saved under this folder in the frame's assets directory"
    },
    {
      "name": "journalStateKey",
      "label": "Journal state key",
      "type": "string",
      "value": "birdSongJournal",
